function foes(){return Object.values(bot.entities).filter(e=>['creeper','skeleton','zombie','spider','witch','enderman'].includes(e.name)&&e.position.distanceTo(bot.entity.position)<14)}
function centered(){const p=bot.entity.position;return Math.abs(p.x-2.5)<.14&&Math.abs(p.z-87.5)<.14}
async function cut(p){alive();const b=bot.blockAt(p);if(!b||!['stone','sand','snow','sandstone','granite','diorite','andesite','gravel','iron_ore','coal_ore','cobblestone','spruce_planks'].includes(b.name))throw Error('CUT_MATERIAL '+p+' '+b?.name);let item;if(['sand','gravel','snow','spruce_planks'].includes(b.name)){await bot.unequip('hand')}else{item=bot.inventory.items().find(i=>i.name===(b.name==='iron_ore'?'stone_pickaxe':'wooden_pickaxe'))||bot.inventory.items().find(i=>i.name==='stone_pickaxe');if(!item)throw Error('NO_PICK');await bot.equip(item,'hand')}if(!bot.canDigBlock(b))throw Error('REACH '+p);let t;try{await Promise.race([bot.dig(b),new Promise((_,r)=>t=setTimeout(()=>{bot.stopDigging();r(Error('CUT_BOUND'))},6000))])}finally{clearTimeout(t)}await ticks(3);}
function stock(){return bot.inventory.items().find(i=>['cobblestone','granite','diorite','andesite','sandstone','spruce_planks','dirt'].includes(i.name))}
async function place(p,item=null){if(full(p))return;const ref=dirs.map(d=>[p.plus(d),d.scaled(-1)]).concat([[p.offset(0,1,0),new Vec3(0,-1,0)],[p.offset(0,-1,0),new Vec3(0,1,0)]]).find(([q])=>full(q));if(!ref)throw Error('NO_PLACE_REF '+p);item=item||stock();if(!item)throw Error('NO_CAP');await bot.equip(item,'hand');await ticks(2);await bot._placeBlockWithOptions(bot.blockAt(ref[0]),ref[1],{forceLook:true,swingArm:'right'});await ticks(4);if(!full(p))throw Error('PLACE_POST '+p)}
function shell(){const p=C();return bot.entity.onGround&&full(p.offset(0,-1,0))&&full(p.offset(0,2,0))&&dirs.every(d=>full(p.plus(d))&&full(p.plus(d).offset(0,1,0)))}
async function center(){for(const a of['x','z'])for(let n=0;n<20&&Math.abs(bot.entity.position[a]-(a==='x'?2.5:87.5))>.04;n++){const sign=Math.sign((a==='x'?2.5:87.5)-bot.entity.position[a]);await bot.lookAt(bot.entity.position.offset(a==='x'?sign*10:0,1.6,a==='z'?sign*10:0),true);bot.setControlState('sneak',true);bot.setControlState('forward',true);await ticks(1);bot.clearControlStates();await ticks(2)}if(!centered())throw Error('CENTER_FAIL')}
async function down(){alive();if(!centered()||!bot.entity.onGround||foes().length)throw Error('DOWN_STATE');const old=C(),next=old.offset(0,-1,0);if(!full(next.offset(0,-1,0)))throw Error('NEXT_FLOOR');for(const d of dirs)for(const dy of[0,1]){const q=next.plus(d).offset(0,dy,0);if(!full(q)&&!(next.y>=65&&['air','snow','sand','grass_block'].includes(bot.blockAt(q)?.name)))throw Error('OPEN_NEXT_WALL '+q+' '+bot.blockAt(q)?.name)}await cut(next);for(let n=0;n<24;n++){await ticks(1);if(bot.entity.onGround&&Math.abs(bot.entity.position.y-next.y)<.05)break}if(!bot.entity.onGround||Math.abs(bot.entity.position.y-next.y)>.05||!centered())throw Error('DOWN_ACTUAL '+bot.entity.position);if(next.y<=64)await place(next.offset(0,2,0));console.log('DOWN',bot.entity.position.toString(),'FULL',shell());}
async function up(){alive();if(!centered()||!bot.entity.onGround)throw Error('UP_STATE');const p=C();if(full(p.offset(0,2,0)))await cut(p.offset(0,2,0));const b=bot.blockAt(p.offset(0,-1,0));if(!full(b.position))throw Error('UP_FLOOR');const item=stock()||bot.inventory.items().find(i=>i.name==='sand');if(!item)throw Error('UP_BLOCK');await bot.equip(item,'hand');await bot.lookAt(b.position.offset(.5,1,.5),true);bot.setControlState('jump',true);try{await ticks(4);await bot._placeBlockWithOptions(b,new Vec3(0,1,0),{forceLook:true,swingArm:'right'})}finally{bot.clearControlStates()}await ticks(10);if(Math.abs(bot.entity.position.y-(p.y+1))>.05||!bot.entity.onGround)throw Error('UP_ACTUAL '+bot.entity.position);console.log('UP',bot.entity.position.toString())}
async function returnCamp(){for(const q of [[3.5,66,85.5],[3.5,66,79.5],[6.5,66,79.5]])await go(...q,5000);await door('enter');await ticks(6);for(const x of[6,7]){const b=bot.blockAt(new Vec3(x,67,81));if(b.getProperties().open){await bot.activateBlock(b);await ticks(6)}}}

async function quarry(n){for(let x=3;x<3+n;x++){const v=new Vec3(x,52,87);for(const q of[v.offset(0,-1,0),v.offset(0,2,0),v.offset(0,0,-1),v.offset(0,1,-1),v.offset(0,0,1),v.offset(0,1,1),v.offset(1,0,0),v.offset(1,1,0)])if(!full(q)||['sand','gravel','lava','water'].includes(bot.blockAt(q).name))throw Error('QUARRY_ENVELOPE '+q+' '+bot.blockAt(q)?.name);await cut(v.offset(0,1,0));await cut(v);await go(x+.5,52,87.5,3500);await ticks(5);console.log('QUARRY_ACTUAL',x,bot.inventory.items().filter(i=>i.name==='cobblestone').map(i=>i.count));}await go(2.5,52,87.5,10000);await center();await place(new Vec3(3,52,87));await place(new Vec3(3,53,87));if(!shell())throw Error('QUARRY_END_SHELL');}

let issue=null;try{if(bot.game.dimension!=='overworld'||bot.health<19||foes().length)throw Error('START');await door('exit');await go(2.5,67,87.5,6000);await center();for(let n=0;n<15;n++)await down();await quarry(10);}catch(e){issue=e.message;console.log('ISSUE',issue);try{if(!dead&&centered()&&C().y<=64)await place(C().offset(0,2,0))}catch(e){console.log('CAP_FAIL',e.message)}}finally{bot.clearControlStates();bot.pathfinder.setGoal(null);bot.removeListener('death',die);console.log('QUARRY_END',JSON.stringify({p:bot.entity.position,hp:bot.health,food:bot.food,dead,issue,shell:shell(),inventory:bot.inventory.items().map(i=>[i.name,i.count,i.durabilityUsed])}))}
